query($endCursor: String) {
  repository(owner: "ohcnetwork", name: "care_fe") {
    pullRequests(states: OPEN, first: 30, after: $endCursor, orderBy: {field: CREATED_AT, direction: DESC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        number
        commits(last: 1) { nodes { commit { committedDate statusCheckRollup { state } } } }
        latestOpinionatedReviews(first: 10) { nodes { state author { login } } }
        reviewRequests(first: 10) { nodes { requestedReviewer { ... on User { login } ... on Team { name } } } }
        comments { totalCount }
        closingIssuesReferences(first: 5) { nodes { number } }
      }
    }
  }
}
EOF
rm -f prs_ci.json
gh api graphql --paginate -F query=@rollup.graphql --jq '.data.repository.pullRequests.nodes[]' | jq -s '.' > prs_ci.json && jq 'length, (map(.number) | unique | length)' prs_ci.json

cd "/private/tmp/claude-501/-Users-bodhishthomas-code-care-fe/cf4cdbbe-a1e2-43de-aa1d-d77f31bdfcef/scratchpad" && cat > reviews.graphql <<'EOF'
query($endCursor: String) {
  repository(owner: "ohcnetwork", name: "care_fe") {
    pullRequests(states: OPEN, first: 30, after: $endCursor, orderBy: {field: CREATED_AT, direction: DESC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        number
        latestOpinionatedReviews(first: 10) { nodes { state submittedAt author { login } } }
        commits(last: 1) { nodes { commit { committedDate } } }
      }
    }
  }
}
EOF
gh api graphql --paginate -F query=@reviews.graphql --jq '.data.repository.pullRequests.nodes[]' | jq -s '.' > prs_reviews_ts.json && jq 'length' prs_reviews_ts.json
echo "--- PRs with outstanding CHANGES_REQUESTED: last CHA review date vs last commit date"
jq -r '.[] | . as $p | ([.latestOpinionatedReviews.nodes[] | select(.state=="CHANGES_REQUESTED")] ) as $cha | select(($cha|length) > 0) | ($cha | map(.submittedAt) | max) as $lastCha | ($p.commits.nodes[0].commit.committedDate) as $lc | [ $p.number, ($lastCha[0:10]), ($lc[0:10]), (if $lc > $lastCha then "AUTHOR_PUSHED_SINCE -> awaiting re-review" else "NO_PUSH_SINCE -> awaiting author" end), ($cha | map(.author.login) | join(",")) ] | @tsv' prs_reviews_ts.json
echo "--- fork (community) PRs by humans"
jq -r '.[] | select(.isCrossRepository and ((.author.login|test("^app/"))|not)) | [.number, .author.login] | @tsv' merged.json
echo "--- bot PR reviews (non daily-playwright)"
jq -r '.[] | select(.author.login | test("^app/(copilot|anthropic)")) | [ .number, .author.login, ([.reviews[] | "\(.s[0:3]):\(.by)"] | join(" ")), ("req:" + (.requested | join(","))), ([.assignees[].login] | join(",")) ] | @tsv' merged.json
